      <span>第 {{page}} / {{pageCount}} 页 · 共 {{total}} 题</span>
      <button :disabled="loading || page>=pageCount" @click="loadPage(page+1)">下一页</button>
      <label>每页 <select v-model.number="pageSize" :disabled="loading" @change="loadPage(1)"><option :value="10">10</option><option :value="20">20</option><option :value="50">50</option></select> 题</label>
    </nav>
  </template>
  <template v-else-if="current">
    <header class="hero practice-head"><button class="back" @click="view='list'">‹ 返回题目列表</button><h1>{{current.title}}</h1><p>{{current.type==='multiple'?'多选题':'单选题'}} · {{current.categoryName}} · {{current.difficulty}}</p></header>
    <article class="card"><p v-if="current.description" class="desc">{{current.description}}</p><div class="options"><button v-for="o in current.options" :key="o.key" :disabled="showAnswer || loading" :class="optionClass(o.key)" @click="toggle(o.key)"><i>{{o.key}}</i><span v-if="studyMode && current.answer.includes(o.key)" aria-label="正确选项">✓</span>{{o.text}}</button></div><button v-if="!showAnswer" class="confirm" :disabled="loading || !selected.length" @click="submitted=true">确认答案</button><button v-if="!showAnswer" class="reveal-answer" :disabled="loading" @click="revealAnswer">查看答案与解析 ›</button><section v-if="showAnswer" class="result" aria-live="polite"><div><span><b>正确答案</b> {{current.answer.join('、')}}</span><span v-if="submitted && !studyMode" :class="isCorrect?'right':'wrong'"><b>你的答案</b> {{selected.join('、')}}</span></div><h2>参考答案与解析</h2><div class="analysis-markdown" v-html="analysisHtml"></div></section></article>
    <footer class="pager"><button class="mode-toggle" :disabled="loading" :aria-pressed="studyMode" @click="toggleStudyMode">{{studyMode ? '切换到答题模式' : '切换到背题模式'}}</button><span>答题卡 {{position+1}}/{{total}}</span><div><button :disabled="loading || position===0" @click="move(-1)">‹ 上一题</button><button :disabled="loading || position===total-1" @click="move(1)">下一题 ›</button></div></footer>
  </template>
</main>
</template>
<script>
import controller from '../api/question-bank-controller'
export default controller
</script>
